//! Kuda の本体。`kuda` と `kudaw` の 2 つのバイナリから呼ばれる。

use anyhow::Result;
use clap::{Parser, Subcommand};
use config::Config;
use paths::Paths;
use std::process::ExitCode;

mod baseline;
mod collector;
mod commands;
mod config;
mod detach;
mod diagnosis;
mod exec;
mod incident;
mod investigation;
mod known_set;
mod lock;
mod logging;
mod metrics;
mod notify;
mod os;
mod paths;
mod probe;
mod store;
mod time;
mod trigger;

#[derive(Parser)]
#[command(
    name = "kuda",
    version,
    about = "PC monitoring harness with LLM-driven investigation"
)]
struct Cli {
    /// Log at debug level and mirror the log to stderr
    #[arg(long, global = true)]
    verbose: bool,

    #[command(subcommand)]
    command: Command,
}

#[derive(Subcommand)]
enum Command {
    /// Run one monitoring cycle (this is what the scheduler invokes)
    Check {
        /// Probe every watch even if its interval has not elapsed
        #[arg(long)]
        force: bool,
    },
    /// Take snapshots and store each successful collector as last_known_good
    Snapshot {
        /// Ignore snapshot_interval and the retry interval
        #[arg(long)]
        force: bool,
        /// Limit to one watch
        #[arg(long)]
        watch: Option<String>,
    },
    /// Build an incident directory and investigate it with an LLM
    Diagnose {
        /// Name of the watch to investigate (the `name` of a [[watch]] in the config;
        /// it must have a [watch.diagnose] table)
        #[arg(long)]
        watch: String,
        /// Only build the incident directory; do not call an LLM
        #[arg(long)]
        dry_run: bool,
        /// Use this backend instead of the one in the config
        #[arg(long)]
        backend: Option<String>,
        /// Investigate an existing incident directory
        #[arg(long)]
        incident: Option<std::path::PathBuf>,
        /// Show desktop notifications when the investigation starts and ends
        #[arg(long)]
        notify: bool,
    },
    /// Show samples, baselines, snapshots and cooldowns for each watch
    Status,
    /// Validate the config file and everything it refers to
    CheckConfig,
    /// Show whether each LLM backend is available
    CheckBackends,
}

fn run(cli: Cli) -> Result<()> {
    let paths = Paths::from_env()?;
    paths.ensure_dirs()?;
    logging::init(&paths.logs_dir, cli.verbose)?;

    let config_path = paths.config_file();
    commands::log_paths(&paths, &config_path);
    let config = Config::load(&config_path)?;
    logging::set_level(config.general.log_level, cli.verbose);

    match cli.command {
        Command::Check { force } => commands::check(&config, &paths, force),
        Command::Snapshot { force, watch } => {
            commands::snapshot(&config, &paths, force, watch.as_deref())
        }
        Command::Diagnose {
            watch,
            dry_run,
            backend,
            incident,
            notify,
        } => commands::diagnose(
            &config,
            &paths,
            commands::DiagnoseOptions {
                watch,
                dry_run,
                backend,
                incident,
                notify,
            },
        ),
        Command::Status => commands::status(&config, &paths),
        Command::CheckConfig => commands::check_config(&config, &paths),
        Command::CheckBackends => commands::check_backends(&config),
    }
}

pub fn main() -> ExitCode {
    match run(Cli::parse()) {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            // ログ初期化前の失敗もあるので、標準エラーにも必ず出す
            log::error!("{error:#}");
            if log::max_level() == log::LevelFilter::Off {
                eprintln!("error: {error:#}");
            }
            ExitCode::FAILURE
        }
    }
}

//! OS 別のディレクトリ解決。Linux は XDG Base Directory Specification に従う。

use crate::os::Os;
use anyhow::{Context, Result, anyhow};
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, PartialEq)]
pub struct Paths {
    pub config_dir: PathBuf,
    pub data_dir: PathBuf,
    pub incidents_dir: PathBuf,
    pub logs_dir: PathBuf,
    pub reports_dir: PathBuf,
    pub lock_dir: PathBuf,
    /// XDG_RUNTIME_DIR が無くロックを state 側へ退避したとき true
    pub lock_fallback: bool,
}

impl Paths {
    pub fn config_file(&self) -> PathBuf {
        self.config_dir.join("config.toml")
    }

    pub fn db_file(&self) -> PathBuf {
        self.data_dir.join("kuda.db")
    }

    pub fn lock_file(&self) -> PathBuf {
        self.lock_dir.join("kuda.lock")
    }

    pub fn from_env() -> Result<Self> {
        Self::resolve(Os::current(), |key| std::env::var(key).ok())
    }

    fn resolve(os: Os, env: impl Fn(&str) -> Option<String>) -> Result<Self> {
        let var = |key: &str| env(key).filter(|v| !v.is_empty());

        if let Some(home) = var("KUDA_HOME") {
            let root =
                std::path::absolute(&home).with_context(|| format!("invalid KUDA_HOME: {home}"))?;
            return Ok(Self::single_root(root));
        }
        if os == Os::Windows {
            // 設定はユーザーに付いて回るもの、それ以外はこの PC に固有のもの
            let roaming = var("APPDATA").ok_or_else(|| anyhow!("APPDATA is not set"))?;
            let local = var("LOCALAPPDATA").ok_or_else(|| anyhow!("LOCALAPPDATA is not set"))?;
            return Ok(Self {
                config_dir: PathBuf::from(roaming).join("kuda"),
                ..Self::single_root(PathBuf::from(local).join("kuda"))
            });
        }

        let home = var("HOME").ok_or_else(|| anyhow!("HOME is not set"))?;
        // 仕様どおり、相対パスの値は無効として既定値へ戻す
        let xdg = |key: &str, default: &str| {
            var(key)
                .map(PathBuf::from)
                .filter(|p| p.is_absolute())
                .unwrap_or_else(|| Path::new(&home).join(default))
                .join("kuda")
        };
        let state = xdg("XDG_STATE_HOME", ".local/state");
        let runtime = var("XDG_RUNTIME_DIR")
            .map(PathBuf::from)
            .filter(|p| p.is_absolute());

        Ok(Self {
            config_dir: xdg("XDG_CONFIG_HOME", ".config"),
            incidents_dir: state.join("incidents"),
            logs_dir: state.join("logs"),
            reports_dir: xdg("XDG_DATA_HOME", ".local/share").join("reports"),
            lock_fallback: runtime.is_none(),
            lock_dir: runtime.map_or_else(|| state.join("run"), |dir| dir.join("kuda")),
            data_dir: state,
        })
    }

    fn single_root(root: PathBuf) -> Self {
        Self {
            data_dir: root.join("data"),
            lock_dir: root.join("data"),
            incidents_dir: root.join("incidents"),
            logs_dir: root.join("logs"),
            reports_dir: root.join("reports"),
            config_dir: root,
            lock_fallback: false,
        }
    }

    /// 書き込み先のディレクトリを用意する
    pub fn ensure_dirs(&self) -> Result<()> {
        for dir in [
            &self.data_dir,
            &self.incidents_dir,
            &self.logs_dir,
            &self.reports_dir,
            &self.lock_dir,
        ] {
            create_private_dir(dir)?;
        }
        Ok(())
    }
}

/// 無ければ 0700 で作成する。既にあるディレクトリのパーミッションは変えない
pub fn create_private_dir(dir: &Path) -> Result<()> {
    let mut builder = std::fs::DirBuilder::new();
    builder.recursive(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::DirBuilderExt;
        builder.mode(0o700);
    }
    builder
        .create(dir)
        .with_context(|| format!("failed to create {}", dir.display()))
}

/// 1 つのパス要素としてそのまま使える名前か。区切り文字や `..` を通さないよう文字種を絞る
pub fn is_safe_name(name: &str) -> bool {
    !name.is_empty()
        && name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_')
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    fn resolve(os: Os, vars: &[(&str, &str)]) -> Result<Paths> {
        let vars: HashMap<String, String> = vars
            .iter()
            .map(|(k, v)| (k.to_string(), v.to_string()))
            .collect();
        Paths::resolve(os, |key| vars.get(key).cloned())
    }

    // Windows 上で実行しても比較が成り立つよう、期待値も join で組み立てる
    fn path(root: &str, rest: &[&str]) -> PathBuf {
        rest.iter().fold(PathBuf::from(root), |p, s| p.join(s))
    }

    #[test]
    fn linux_defaults_when_unset_or_empty() {
        let paths = resolve(Os::Linux, &[("HOME", "/home/u"), ("XDG_STATE_HOME", "")]).unwrap();
        let state = path("/home/u", &[".local/state", "kuda"]);
        assert_eq!(
            paths.config_file(),
            path("/home/u", &[".config", "kuda", "config.toml"])
        );
        assert_eq!(paths.db_file(), state.join("kuda.db"));
        assert_eq!(paths.logs_dir, state.join("logs"));
        assert_eq!(paths.incidents_dir, state.join("incidents"));
        assert_eq!(
            paths.reports_dir,
            path("/home/u", &[".local/share", "kuda", "reports"])
        );
    }

    #[test]
    fn linux_honors_absolute_xdg_values() {
        // 絶対パス判定はビルド先 OS に依存するので Unix でのみ確かめる
        if cfg!(windows) {
            return;
        }
        let paths = resolve(
            Os::Linux,
            &[
                ("HOME", "/home/u"),
                ("XDG_CONFIG_HOME", "/c"),
                ("XDG_STATE_HOME", "/s"),
                ("XDG_DATA_HOME", "/d"),
                ("XDG_RUNTIME_DIR", "/r"),
            ],
        )
        .unwrap();
        assert_eq!(paths.config_dir, Path::new("/c/kuda"));
        assert_eq!(paths.db_file(), Path::new("/s/kuda/kuda.db"));
        assert_eq!(paths.reports_dir, Path::new("/d/kuda/reports"));
        assert_eq!(paths.lock_file(), Path::new("/r/kuda/kuda.lock"));
        assert!(!paths.lock_fallback);
    }

    #[test]
    fn linux_ignores_relative_xdg_values() {
        let paths = resolve(
            Os::Linux,
            &[
                ("HOME", "/home/u"),
                ("XDG_CONFIG_HOME", "relative/config"),
                ("XDG_RUNTIME_DIR", "relative/run"),
            ],
        )
        .unwrap();
        assert_eq!(paths.config_dir, path("/home/u", &[".config", "kuda"]));
        assert!(paths.lock_fallback);
    }

    #[test]
    fn linux_lock_falls_back_to_state_without_runtime_dir() {
        let paths = resolve(Os::Linux, &[("HOME", "/home/u")]).unwrap();
        assert_eq!(
            paths.lock_file(),
            path("/home/u", &[".local/state", "kuda", "run", "kuda.lock"])
        );
        assert!(paths.lock_fallback);
    }

    #[test]
    fn windows_puts_config_in_appdata_and_the_rest_in_localappdata() {
        let paths = resolve(
            Os::Windows,
            &[("APPDATA", "/roaming"), ("LOCALAPPDATA", "/local")],
        )
        .unwrap();
        let root = Path::new("/local").join("kuda");
        assert_eq!(
            paths.config_file(),
            path("/roaming", &["kuda", "config.toml"])
        );
        assert_eq!(paths.db_file(), root.join("data").join("kuda.db"));
        assert_eq!(paths.lock_file(), root.join("data").join("kuda.lock"));
        assert_eq!(paths.reports_dir, root.join("reports"));
    }

    #[test]
    fn kuda_home_overrides_every_os() {
        let home = std::env::temp_dir().join("kuda-home");
        let home_str = home.to_str().unwrap();
        for os in [Os::Windows, Os::Linux] {
            let paths = resolve(os, &[("KUDA_HOME", home_str), ("HOME", "/home/u")]).unwrap();
            assert_eq!(paths.config_file(), home.join("config.toml"));
            assert_eq!(paths.db_file(), home.join("data").join("kuda.db"));
            assert_eq!(paths.logs_dir, home.join("logs"));
        }
    }

    #[test]
    fn missing_home_is_an_error() {
        assert!(resolve(Os::Linux, &[]).is_err());
        assert!(resolve(Os::Windows, &[]).is_err());
        assert!(resolve(Os::Windows, &[("APPDATA", "/roaming")]).is_err());
        assert!(resolve(Os::Windows, &[("LOCALAPPDATA", "/local")]).is_err());
    }

    #[cfg(unix)]
    #[test]
    fn creates_dirs_0700_and_keeps_existing_mode() {
        use std::os::unix::fs::PermissionsExt;
        let root = std::env::temp_dir().join(format!("kuda-perm-{}", std::process::id()));
        let dir = root.join("a");
        create_private_dir(&dir).unwrap();
        let mode = |p: &Path| std::fs::metadata(p).unwrap().permissions().mode() & 0o777;
        assert_eq!(mode(&dir), 0o700);
        std::fs::set_permissions(&dir, std::fs::Permissions::from_mode(0o750)).unwrap();
        create_private_dir(&dir).unwrap();
        assert_eq!(mode(&dir), 0o750);
        std::fs::remove_dir_all(root).unwrap();
    }
}

