#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::LocalMode;
    use std::io::{Read, Write};
    use std::net::TcpListener;
    use std::sync::mpsc;

    /// 1 件のリクエストに応答し、受け取った内容を返すサーバー
    fn mock_server(status: &'static str, body: String) -> (String, mpsc::Receiver<String>) {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        let url = format!("http://{}/v1/", listener.local_addr().unwrap());
        let (sender, receiver) = mpsc::channel();
        std::thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            stream
                .set_read_timeout(Some(Duration::from_millis(300)))
                .unwrap();
            let mut received = Vec::new();
            let mut chunk = [0; 4096];
            while let Ok(n) = stream.read(&mut chunk) {
                if n == 0 {
                    break;
                }
                received.extend_from_slice(&chunk[..n]);
            }
            let reply = format!(
                "HTTP/1.1 {status}\r\nContent-Length: {}\r\n\r\n{body}",
                body.len()
            );
            let _ = stream.write_all(reply.as_bytes());
            let _ = sender.send(String::from_utf8_lossy(&received).into_owned());
        });
        (url, receiver)
    }

    fn backend(endpoint: String) -> Local {
        Local(LocalBackend {
            endpoint,
            model: "test-model".to_string(),
            mode: LocalMode::AnalyzeOnly,
        })
    }

    fn with_incident_dir<T>(name: &str, test: impl FnOnce(&Path) -> T) -> T {
        let dir = crate::testutil::TempDir::new(&format!("local-{name}"));
        std::fs::write(dir.join("summary.md"), "summary-marker").unwrap();
        test(&dir)
    }

    fn request(dir: &Path) -> Request<'_> {
        Request {
            prompt: "prompt-marker",
            incident_dir: dir,
            work_dir: dir,
            allowed_commands: &[],
            timeout: Duration::from_secs(5),
        }
    }

    #[test]
    fn sends_prompt_and_evidence_and_reads_the_reply() {
        let reply = json!({ "choices": [{ "message": { "content": "## 症状" } }] });
        let (url, received) = mock_server("200 OK", reply.to_string());
        let text = with_incident_dir("ok", |dir| backend(url).run(&request(dir)).unwrap());
        assert_eq!(text, "## 症状");
        let sent = received.recv().unwrap();
        assert!(sent.starts_with("POST /v1/chat/completions"));
        for marker in ["prompt-marker", "summary-marker", "test-model"] {
            assert!(sent.contains(marker), "{marker}");
        }
    }

    #[test]
    fn empty_reply_is_an_error() {
        let reply = json!({ "choices": [{ "message": { "content": " " } }] });
        let (url, _received) = mock_server("200 OK", reply.to_string());
        with_incident_dir("empty", |dir| {
            assert!(backend(url).run(&request(dir)).is_err());
        });
    }

    #[test]
    fn server_error_is_an_error() {
        let (url, _received) = mock_server("500 Oops", String::new());
        with_incident_dir("500", |dir| {
            assert!(backend(url).run(&request(dir)).is_err());
        });
    }

    #[test]
    fn availability_follows_the_models_endpoint() {
        let (url, _received) = mock_server("200 OK", "{}".to_string());
        assert!(backend(url).available().is_ok());
        let closed = TcpListener::bind("127.0.0.1:0").unwrap();
        let url = format!("http://{}/v1", closed.local_addr().unwrap());
        drop(closed);
        assert!(backend(url).available().is_err());
    }

    #[test]
    fn does_not_follow_symlinked_evidence() {
        let root = crate::testutil::TempDir::new("local-link");
        let dir = root.join("incident");
        std::fs::create_dir_all(&dir).unwrap();
        let outside = root.join("secret.txt");
        std::fs::write(&outside, "secret-marker").unwrap();
        std::fs::write(dir.join("diff.md"), "diff-marker").unwrap();
        #[cfg(unix)]
        let linked = std::os::unix::fs::symlink(&outside, dir.join("summary.md"));
        #[cfg(windows)]
        let linked = std::os::windows::fs::symlink_file(&outside, dir.join("summary.md"));
        let text = linked.is_ok().then(|| evidence(&dir));
        std::fs::remove_dir_all(&root).unwrap();
        // Windows では開発者モードか管理者でないとリンクを作れないので、そのときは確かめない
        let Some(text) = text else {
            eprintln!("skipped: cannot create a symlink here");
            return;
        };
        assert!(!text.contains("secret-marker"), "{text}");
        assert!(text.contains("diff-marker"), "{text}");
    }

    #[test]
    fn truncates_on_char_boundaries() {
        assert_eq!(truncate("あいう", 4), "あ");
        assert_eq!(truncate("abc", 10), "abc");
    }
}

//! 日付ローテーションするファイルログ。GUI サブシステムのリリースビルドでは
//! 標準出力が見えないため、ログは必ずファイルへ出す。

use anyhow::{Context, Result};
use chrono::{Local, NaiveDate};
use log::{Level, LevelFilter, Log, Metadata, Record};
use std::fs::{File, OpenOptions};
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::Mutex;

struct FileLogger {
    dir: PathBuf,
    mirror_stderr: bool,
    /// 開いているファイルとその日付。日付が変わったら開き直す
    current: Mutex<Option<(NaiveDate, File)>>,
}

impl Log for FileLogger {
    fn enabled(&self, metadata: &Metadata) -> bool {
        metadata.target().starts_with("kuda")
    }

    fn log(&self, record: &Record) {
        if !self.enabled(record.metadata()) {
            return;
        }
        let now = Local::now();
        let line = format!(
            "{} {:<5} [{}] {}\n",
            now.format("%Y-%m-%dT%H:%M:%S%:z"),
            record.level(),
            std::process::id(),
            record.args()
        );
        if self.mirror_stderr || record.level() == Level::Error {
            eprint!("{line}");
        }
        let Ok(mut current) = self.current.lock() else {
            return;
        };
        let today = now.date_naive();
        if current.as_ref().is_none_or(|(date, _)| *date != today) {
            let opened = OpenOptions::new()
                .create(true)
                .append(true)
                .open(self.dir.join(log_file_name(today)));
            *current = opened.ok().map(|file| (today, file));
        }
        if let Some((_, file)) = current.as_mut() {
            let _ = file.write_all(line.as_bytes());
        }
    }

    fn flush(&self) {}
}

fn log_file_name(date: NaiveDate) -> String {
    format!("kuda-{}.log", date.format("%Y-%m-%d"))
}

fn parse_log_date(file_name: &str) -> Option<NaiveDate> {
    let date = file_name.strip_prefix("kuda-")?.strip_suffix(".log")?;
    NaiveDate::parse_from_str(date, "%Y-%m-%d").ok()
}

pub fn init(dir: &Path, verbose: bool) -> Result<()> {
    log::set_boxed_logger(Box::new(FileLogger {
        dir: dir.to_path_buf(),
        mirror_stderr: verbose,
        current: Mutex::new(None),
    }))
    .context("logger is already initialized")?;
    set_level(LevelFilter::Info, verbose);
    Ok(())
}

/// 設定を読む前にもログを出せるよう、レベルは初期化と分けて後から設定する
pub fn set_level(level: LevelFilter, verbose: bool) {
    log::set_max_level(if verbose { LevelFilter::Debug } else { level });
}

/// `retention_days` より古いログを削除する
pub fn prune(dir: &Path, retention_days: u32, today: NaiveDate) -> Result<()> {
    for entry in std::fs::read_dir(dir)? {
        let entry = entry?;
        let Some(date) = entry.file_name().to_str().and_then(parse_log_date) else {
            continue;
        };
        if (today - date).num_days() > i64::from(retention_days) {
            std::fs::remove_file(entry.path())?;
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn prune_removes_only_expired_kuda_logs() {
        let dir = std::env::temp_dir().join(format!("kuda-logs-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let today = NaiveDate::from_ymd_opt(2026, 11, 20).unwrap();
        for name in ["kuda-2026-11-06.log", "kuda-2026-11-05.log", "other.log"] {
            std::fs::write(dir.join(name), "").unwrap();
        }
        prune(&dir, 14, today).unwrap();
        assert!(dir.join("kuda-2026-11-06.log").exists());
        assert!(!dir.join("kuda-2026-11-05.log").exists());
        assert!(dir.join("other.log").exists());
        std::fs::remove_dir_all(dir).unwrap();
    }
}

